mapper.select:
/* emailMapper.getEmailListCount */
SELECT COUNT(EMAIL_ID) AS CNT
  FROM OP_EMAIL OE

mapper.insert:
/* emailMapper.insertEmail */
INSERT INTO OP_EMAIL (
	SUBJECT
	,CONTENT
	,SEND_DATE
	,STATUS
	,AUTH_TARGET
	,FRST_REGISTER_ID
	,FRST_REGIST_PNTTM
	,LAST_UPDUSR_ID
	,LAST_UPDT_PNTTM
) VALUES (
	#{subject}
	,#{content}

	,DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')


	,#{sendDate}

	,'R'
	,#{authTarget}
	,#{frstRegisterId}
	,now()
	,#{frstRegisterId}
	,now()
)

INSERT INTO OP_EMAIL_FILE (
	EMAIL_ID
	,FILE_NAME
	,FILE_TY
	,"ORDERING"
	,CREATED_DATE
	,ORG_FILE_NAME
) VALUES (
	#{emailId}
	,#{fileName}
	,#{fileTy}
	,(SELECT NVL(MAX("ORDERING"),1) FROM OP_EMAIL_FILE WHERE EMAIL_ID = #{emailId})
	,DATE_FORMAT(NOW(),'%Y%m%d%H%i%s')
	,#{orgFileName}
)

mapper.update:
/* emailMapper.updateEmailStatus */
UPDATE OP_EMAIL
   SET STATUS = #{status}
 WHERE EMAIL_ID = #{emailId}

mapper.insert:
/* emailMapper.insertEmailDetail */
INSERT INTO OP_EMAIL_DETAIL (
	EMAIL_ID
	,AUTHORITY
) VALUES (
	#{emailId}
	,#{authority}
)
